  ('4061ef4d-3999-4dad-9f6f-43c9a0d053e3', $$Wiskunde A$$, $$HAVO$$, $$Levensduur van apparaten$$, $$HAVO Wiskunde A 2026-II$$),
  ('115b084b-5495-4c9d-880d-70a78721c0c0', $$Wiskunde A$$, $$HAVO$$, $$Eitje koken op vakantie$$, $$HAVO Wiskunde A 2026-II$$);

insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('85376a2d-439c-4d5c-912e-01a414cb385b', 'e534c332-b36c-4527-bfa3-388eae1144c2', $$inleiding: verwerking van plasticafval$$,
   $$wiskunde-a-havo-2026-ii-plasticafval-context1.png$$,
   $$Jaarlijks produceren wij een grote hoeveelheid plasticafval. Een groot deel hiervan wordt ingezameld en daarna gerecycled, verbrand of op een afvalberg gestort. Het deel dat niet wordt ingezameld, wordt niet verwerkt.$$, 'inline'),
  ('3357ac9f-3440-449c-a382-dff36a35e35b', 'e534c332-b36c-4527-bfa3-388eae1144c2', $$figuur plasticafval in Europa: toelichting$$,
   $$wiskunde-a-havo-2026-ii-plasticafval-context2.png$$,
   $$In de figuur zie je voor Europa welk deel van het plasticafval in 2005 en in 2019 werd gerecyled, verbrand, gestort of niet verwerkt.$$, 'inline'),
  ('e360598c-cf46-430f-bd13-5bb795cc2033', 'e534c332-b36c-4527-bfa3-388eae1144c2', $$figuur: plasticafval in Europa 2005 en 2019$$,
   $$wiskunde-a-havo-2026-ii-plasticafval-context3.png$$,
   $$figuur plasticafval in Europa
staafdiagram; verticale as: percentage (0 – 70); categorieën: gerecycled, verbrand, gestort, niet verwerkt
Legenda: 2005, 2019$$, 'inline'),
  ('1e6bcaa5-62cf-4f8a-88d3-92f2901026f1', 'e534c332-b36c-4527-bfa3-388eae1144c2', $$totale hoeveelheid plasticafval 2005 en 2019$$,
   $$wiskunde-a-havo-2026-ii-plasticafval-context4.png$$,
   $$In 2005 werd er in Europa in totaal 12,26 miljoen ton plasticafval geproduceerd. In 2019 was dit gestegen naar 15,26 miljoen ton.$$, 'inline'),
  ('17c591f7-f527-465e-8cae-07568df78ba8', 'e534c332-b36c-4527-bfa3-388eae1144c2', $$aanname: percentage gestort lineair gedaald$$,
   $$wiskunde-a-havo-2026-ii-plasticafval-context5.png$$,
   $$In de figuur is te zien dat in 2005 in Europa 62% van het plasticafval werd gestort. In 2019 was dit percentage gedaald naar 44%. We nemen aan dat het percentage gestort plasticafval in de periode 2005 - 2019 lineair is gedaald.$$, 'inline'),
  ('c1be39c6-4ea3-4e90-a383-af84f4d46ec5', 'e534c332-b36c-4527-bfa3-388eae1144c2', $$exponentiële toename: elke 15 jaar 132% erbij$$,
   $$wiskunde-a-havo-2026-ii-plasticafval-context6.png$$,
   $$Het gewicht aan plasticafval dat jaarlijks wereldwijd wordt geproduceerd neemt exponentieel toe. Elke 15 jaar komt er 132% bij.$$, 'inline'),
  ('f9e829bb-a318-4c5e-8e78-346813ceee0c', 'e534c332-b36c-4527-bfa3-388eae1144c2', $$formules 1, 2 en 3 voor Pb, Ps en Pnv$$,
   $$wiskunde-a-havo-2026-ii-plasticafval-context7.png$$,
   $$De afgelopen decennia nam wereldwijd het percentage verbrand plasticafval Pb toe. Het percentage gestort plasticafval Ps en het percentage niet verwerkt plasticafval Pnv namen wereldwijd juist af.
Bij benadering geldt:
Pb = 0,42 · t + 13,17 (formule 1)
Ps = −0,47 · t + 55,73 (formule 2)
Pnv = −0,24 · t + 25,95 (formule 3)
Hierin is t het aantal jaren na 2005.$$, 'inline'),
  ('62482b2e-918c-4dfe-9c24-e6c515025390', 'e534c332-b36c-4527-bfa3-388eae1144c2', $$moment waarop Pb groter is dan Ps$$,
   $$wiskunde-a-havo-2026-ii-plasticafval-context8.png$$,
   $$In 2005 was Pb kleiner dan Ps. Volgens formule 1 en 2 komt er echter een moment waarop Pb groter zal zijn dan Ps.$$, 'inline'),
  ('4524fb95-4fef-40f6-9a40-816e11448bb5', 'e534c332-b36c-4527-bfa3-388eae1144c2', $$formule 4 voor Pr$$,
   $$wiskunde-a-havo-2026-ii-plasticafval-context9.png$$,
   $$Voor de toekomst zijn we vooral geïnteresseerd in het percentage wereldwijd gerecyled plasticafval Pr. Omdat de vier percentages Pb, Ps, Pnv en Pr samen 100% moeten zijn, kun je met behulp van formule 1, 2 en 3 een formule opstellen voor Pr. Deze formule is van de vorm:
Pr = ... · t + ... (formule 4)
Hierin is t het aantal jaren na 2005.
Op de puntjes in formule 4 moeten getallen staan.$$, 'inline'),
  ('7882bfef-5e32-4bf3-94d5-9dcbdf3fac47', '00694cd3-c83e-4022-9604-66a59ecdb4f0', $$inleiding: wisselende waarnemers$$,
   $$wiskunde-a-havo-2026-ii-huisartsen-context1.png$$,
   $$Een groot deel van de huisartsen in Nederland heeft een eigen praktijk of werkt op vaste basis in de praktijk van een andere huisarts. Het andere (kleinere) deel van de huisartsen vervangt op flexibele basis collega-huisartsen. Deze huisartsen worden wisselende waarnemers genoemd.$$, 'inline'),
  ('30acb7c4-3332-408a-b4ec-54fe22215fa9', '00694cd3-c83e-4022-9604-66a59ecdb4f0', $$formule 1: aantal wisselende waarnemers HW$$,
   $$wiskunde-a-havo-2026-ii-huisartsen-context2.png$$,
   $$Het aantal wisselende waarnemers HW stijgt snel en kan benaderd worden met de volgende formule:
HW = 1983 · 1,0576ᵗ (formule 1)
Hierin is t het aantal jaren, met t = 0 op 1 januari 2015.$$, 'inline'),
  ('4a49aaa2-208e-4a25-98c2-851024a3b3fc', '00694cd3-c83e-4022-9604-66a59ecdb4f0', $$lineaire stijging totaal aantal huisartsen 2006-2015$$,
   $$wiskunde-a-havo-2026-ii-huisartsen-context3.png$$,
   $$Het totaal aantal huisartsen stijgt ook, maar minder snel. Tussen 1 januari 2006 en 1 januari 2015 is het totaal aantal huisartsen lineair gestegen tot 11 622. Dit was een toename van 20%. Uit deze gegevens is af te leiden dat in deze periode het totaal aantal huisartsen jaarlijks toenam met 215 huisartsen (afgerond op gehelen). De berekening van deze jaarlijkse toename op basis van de gegevens geeft een resultaat met meer cijfers achter de komma.$$, 'inline'),
  ('1750db2b-b7f5-4dff-ac20-a053f727340c', '00694cd3-c83e-4022-9604-66a59ecdb4f0', $$formule 2: totaal aantal huisartsen HTotaal$$,
   $$wiskunde-a-havo-2026-ii-huisartsen-context4.png$$,
   $$We nemen aan dat de toename van het totaal aantal huisartsen zich na 2015 op dezelfde wijze voortzet. Voor het totaal aantal huisartsen HTotaal geldt dan bij benadering:
HTotaal = 215 · t + 11 622 (formule 2)
Hierin is t het aantal jaren, met t = 0 op 1 januari 2015.$$, 'inline'),
  ('b5505544-fdc5-474e-9403-a0431939610b', '00694cd3-c83e-4022-9604-66a59ecdb4f0', $$tekort aan huisartsen$$,
   $$wiskunde-a-havo-2026-ii-huisartsen-context5.png$$,
   $$Ondanks het stijgende aantal huisartsen is er een tekort. Daarom is het belangrijk dat voldoende geneeskundestudenten voor het beroep van huisarts kiezen.$$, 'inline'),
  ('91f9903a-b9db-4566-856e-7b6467ac1529', '00694cd3-c83e-4022-9604-66a59ecdb4f0', $$enquête onder geneeskundestudenten$$,
   $$wiskunde-a-havo-2026-ii-huisartsen-context6.png$$,
   $$Aan geneeskundestudenten is gevraagd of ze huisarts willen worden. In de figuur zie je de resultaten bij deze vraag.$$, 'inline'),
  ('fceee8f3-8bbf-448c-b2f9-d1d562b98c9d', '00694cd3-c83e-4022-9604-66a59ecdb4f0', $$figuur: resultaten bij de vraag ‘Zou je huisarts willen worden?’$$,
   $$wiskunde-a-havo-2026-ii-huisartsen-context7.png$$,
   $$figuur resultaten bij de vraag ‘Zou je huisarts willen worden?’
gestapeld staafdiagram (0% – 100%)
eerste studiejaar: nee 12% | waarschijnlijk niet 24% | misschien 14% | waarschijnlijk wel 38% | ja 12%
zesde studiejaar: nee 3% | waarschijnlijk niet 19% | misschien 15% | waarschijnlijk wel 44% | ja 19%
Legenda: nee, waarschijnlijk niet, misschien, waarschijnlijk wel, ja$$, 'inline'),
  ('fa13f86f-4519-436d-a061-8cd9da8585a9', '00694cd3-c83e-4022-9604-66a59ecdb4f0', $$verschil eerste en zesde studiejaar$$,
   $$wiskunde-a-havo-2026-ii-huisartsen-context8.png$$,
   $$In de figuur is te zien dat er een verschil is in de mate waarin geneeskundestudenten uit het eerste studiejaar en uit het zesde studiejaar een voorkeur hebben om huisarts te worden.$$, 'inline'),
  ('abf1c1b2-d4fd-49f8-a20c-61422795a44f', '00694cd3-c83e-4022-9604-66a59ecdb4f0', $$steekproef zesde studiejaar: 19% ‘ja’, 95%-betrouwbaarheidsinterval$$,
   $$wiskunde-a-havo-2026-ii-huisartsen-context9.png$$,
   $$De vraag ‘Zou je huisarts willen worden?’ is slechts aan een deel van de geneeskundestudenten in het zesde studiejaar gesteld. Het gaat dus om een steekproef. Van de geneeskundestudenten uit het zesde studiejaar die deelnamen aan de steekproef gaf 19% het antwoord ‘ja’. Op basis van de steekproefomvang is berekend dat het 95%-betrouwbaarheidsinterval voor het percentage geneeskundestudenten uit het zesde studiejaar dat ‘ja’ heeft geantwoord [13,91;24,09] is.$$, 'inline'),
  ('52c2c6ad-5cc5-41c8-96fd-81a297dde8bf', 'e653d16a-853a-4f23-8e84-bff662ac71ee', $$inleiding: verhouding V = S/L met figuur 1$$,
   $$wiskunde-a-havo-2026-ii-spanwijdte-en-lichaamslengte-context1.png$$,
   $$Bij de meeste mensen is de spanwijdte van de armen S net iets groter dan de lichaamslengte L. Zie figuur 1.
Met de volgende formule kun je de verhouding V tussen S en L berekenen:
V = S / L met S en L in meter
Het vermoeden bestaat dat de grootte van de verhouding V van invloed is op de prestatie van sporters binnen de vechtsport.
figuur 1
silhouet van een persoon met gespreide armen; S: spanwijdte (horizontaal), L: lichaamslengte (verticaal)$$, 'inline'),
  ('f4a3de23-0660-4a8b-aa83-7da9cb18b5b3', 'e653d16a-853a-4f23-8e84-bff662ac71ee', $$Rico Verhoeven en Badr Hari: lengte en V$$,
   $$wiskunde-a-havo-2026-ii-spanwijdte-en-lichaamslengte-context2.png$$,
   $$In 2019 vochten de twee Nederlandse vechters Rico Verhoeven en Badr Hari tegen elkaar. Rico was 1,96 m lang met V = 1,071 en Badr was 1,98 m lang met V = 1,079.$$, 'inline'),
  ('684925c1-1a78-41ee-a59c-2acf461b79c2', 'e653d16a-853a-4f23-8e84-bff662ac71ee', $$vechter A laagste en vechter B hoogste waarde van V$$,
   $$wiskunde-a-havo-2026-ii-spanwijdte-en-lichaamslengte-context3.png$$,
   $$Onder andere bij de vechtsport MMA (mixed martial arts) is onderzocht of de verhouding V van invloed is op de prestatie van de vechters. In het onderzoek kwamen een laagste en een hoogste waarde van V voor:
− vechter A had de laagste waarde van V
− vechter B had de hoogste waarde van V
Stel dat vechter A en vechter B dezelfde spanwijdte hebben.$$, 'inline'),
  ('ad128c61-0364-4307-bd1e-ae1966e6f177', 'e653d16a-853a-4f23-8e84-bff662ac71ee', $$vechter met S = L + 0,025 en V = 1,01445$$,
   $$wiskunde-a-havo-2026-ii-spanwijdte-en-lichaamslengte-context4.png$$,
   $$In het onderzoek kwam ook een vechter voor met een spanwijdte die 2,5 cm langer was dan zijn lichaamslengte. Voor deze vechter geldt dus S = L + 0,025. De verhouding V die bij de vechter hoort is V = 1,01445.$$, 'inline'),
  ('338e90ae-d691-49e7-92bf-06789098fcf4', 'e653d16a-853a-4f23-8e84-bff662ac71ee', $$tabel: verhouding V per lichte gewichtsklasse$$,
   $$wiskunde-a-havo-2026-ii-spanwijdte-en-lichaamslengte-context5.png$$,
   $$De UFC, de grootste MMA-organisatie ter wereld, verdeelt de vechters in acht verschillende gewichtsklassen. In 2018 is per gewichtsklasse onderzoek gedaan naar de verhouding V van de vechters. In de tabel zijn de resultaten te zien van een steekproef onder de vechters uit de vier lichtste gewichtsklassen.
tabel (verhouding V)
gewichtsklasse | minimum | gemiddelde | maximum | standaardafwijking
vlieggewicht | 0,984 | 1,010 | 1,067 | 0,021
bantamgewicht | 0,956 | 1,023 | 1,077 | 0,028
vedergewicht | 0,942 | 1,022 | 1,075 | 0,027
lichtgewicht | 0,985 | 1,029 | 1,058 | 0,028$$, 'inline'),
  ('84255718-11b3-4148-82e2-3554ec861366', 'e653d16a-853a-4f23-8e84-bff662ac71ee', $$figuur 2: boxplots van V voor zware gewichtsklassen en drie uitspraken$$,
   $$wiskunde-a-havo-2026-ii-spanwijdte-en-lichaamslengte-context6.png$$,
   $$In figuur 2 is voor de vier zwaarste gewichtsklassen de verdeling van de verhouding V met boxplots weergegeven. Met een zwarte stip is voor elke gewichtsklasse de waarde van de verhouding V voor de kampioen aangegeven.
figuur 2
boxplots van de verhouding V voor weltergewicht, middengewicht, licht-zwaargewicht en zwaargewicht; horizontale as: verhouding V (0,975 – 1,100)
Op basis van figuur 2 worden drie uitspraken gedaan:
I De kampioen in elk van de vier gewichtsklassen behoort tot de 25% vechters met de hoogste waarde van V in die gewichtsklasse.
II De meerderheid van de vechters in elk van de vier gewichtsklassen heeft een verhouding V met een waarde groter dan 1,025.
III Op basis van de vuistregels op het formuleblad is het verschil tussen elk tweetal gewichtsklassen gering, als we kijken naar de verdeling van de verhouding V.$$, 'inline'),
  ('6229285a-7eef-4164-8b1e-9b5732806aaf', '4061ef4d-3999-4dad-9f6f-43c9a0d053e3', $$inleiding: levensduur van apparaten$$,
   $$wiskunde-a-havo-2026-ii-levensduur-van-apparaten-context1.png$$,
   $$Een apparaat, zoals een vaatwasser of een stofzuiger, gaat na verloop van tijd een keer kapot. Het apparaat is dan aan het einde van zijn levensduur.$$, 'inline'),
  ('7f040bfc-a885-447d-b82a-3c3dd031b7c1', '4061ef4d-3999-4dad-9f6f-43c9a0d053e3', $$onderzoek levensduur vaatwassers type A en B$$,
   $$wiskunde-a-havo-2026-ii-levensduur-van-apparaten-context2.png$$,
   $$Een fabrikant heeft jarenlang onderzoek gedaan naar de levensduur van twee van zijn vaatwassers: type A en type B. De onderzoeksresultaten zijn verwerkt in de figuur.$$, 'inline'),
  ('666b1b39-dbe4-462f-bb5b-b3f15dd09339', '4061ef4d-3999-4dad-9f6f-43c9a0d053e3', $$figuur: percentage kapotte vaatwassers na t gebruiksjaren$$,
   $$wiskunde-a-havo-2026-ii-levensduur-van-apparaten-context3.png$$,
   $$figuur percentage kapotte vaatwassers na t gebruiksjaren
twee S-vormige grafieken (type A doorgetrokken, type B gestippeld); verticale as: percentage kapot (0 – 100); horizontale as: t (in jaren) (0 – 13)$$, 'inline'),
  ('4f40b288-7df6-493f-a9b9-0ebc0d8776ef', '4061ef4d-3999-4dad-9f6f-43c9a0d053e3', $$voorbeeld aflezen: 80% werkte nog na 5,5 jaar$$,
   $$wiskunde-a-havo-2026-ii-levensduur-van-apparaten-context4.png$$,
   $$In de figuur kun je bijvoorbeeld aflezen dat van beide typen vaatwassers 80% nog werkte na ongeveer 5,5 gebruiksjaren.$$, 'inline'),
  ('70a2ef27-b0a5-41d9-937f-09197466dd7f', '4061ef4d-3999-4dad-9f6f-43c9a0d053e3', $$25% van de vaatwassers werkte nog$$,
   $$wiskunde-a-havo-2026-ii-levensduur-van-apparaten-context5.png$$,
   $$Het aantal gebruiksjaren t waarbij 25% van de vaatwassers nog werkte, is voor type A en type B verschillend.$$, 'inline'),
  ('a6a5058c-c71c-4487-aa7c-5c1bd2b86409', '4061ef4d-3999-4dad-9f6f-43c9a0d053e3', $$formule 1 met vaste waarden s en v$$,
   $$wiskunde-a-havo-2026-ii-levensduur-van-apparaten-context6.png$$,
   $$Fabrikanten gebruiken formules om het percentage P van de apparaten dat kapot is na t gebruiksjaren te schatten. Zo’n formule is van de vorm:
P = 100 · (1 − 0,368^((t/s)^v)) (formule 1)
Hierin zijn s en v vaste waarden, die horen bij een bepaald apparaat.$$, 'inline'),
  ('e2117254-6879-4c25-80cc-411a169a335e', '4061ef4d-3999-4dad-9f6f-43c9a0d053e3', $$broodroosters: s = 4 en v = 2, formule 2$$,
   $$wiskunde-a-havo-2026-ii-levensduur-van-apparaten-context7.png$$,
   $$Een fabrikant gebruikt formule 1 voor de levensduur van zijn broodroosters. Bij de broodroosters horen s = 4 en v = 2. Formule 1 is dan te herleiden tot:
P = 100 − 100 · 0,368^(0,0625 · t²) (formule 2)
Met P het percentage van de apparaten dat kapot is na t gebruiksjaren.$$, 'inline'),
  ('e8022f23-700a-49cd-956b-79b39b532e66', '4061ef4d-3999-4dad-9f6f-43c9a0d053e3', $$op den duur gaan alle broodroosters kapot$$,
   $$wiskunde-a-havo-2026-ii-levensduur-van-apparaten-context8.png$$,
   $$Op den duur gaan alle broodroosters een keer kapot.$$, 'inline'),
  ('9493cc35-8938-4fdf-afaf-8f2f59bfd4a6', '4061ef4d-3999-4dad-9f6f-43c9a0d053e3', $$stofzuigers: v = 3, 736 van de 920 kapot na zes jaar$$,
   $$wiskunde-a-havo-2026-ii-levensduur-van-apparaten-context9.png$$,
   $$Een fabrikant gebruikt formule 1 voor de levensduur van zijn stofzuigers. Bij de stofzuigers hoort v = 3. Uit een marktonderzoek is bekend dat 736 van de 920 verkochte stofzuigers kapot waren na zes gebruiksjaren.$$, 'inline'),
  ('6336f397-9efd-423b-b820-80205f60a9e8', '115b084b-5495-4c9d-880d-70a78721c0c0', $$inleiding: eitje koken op zeeniveau en op 2000 m$$,
   $$wiskunde-a-havo-2026-ii-eitje-koken-op-vakantie-context1.png$$,
   $$Richard gaat in de zomer op kampeervakantie, eerst naar de Zuid-Franse kust op zeeniveau en later naar de Franse Alpen op 2000 meter boven zeeniveau. Op beide plaatsen gaat hij dagelijks een ei koken met dezelfde gasbrander, dezelfde pan en evenveel water met dezelfde begintemperatuur. Hij vraagt zich af op welke plaats het bereiden van het ei het langst zal duren.$$, 'inline'),
  ('82d498e1-7437-4936-807f-543423a7d10f', '115b084b-5495-4c9d-880d-70a78721c0c0', $$opwarmen water: lineair met 14,5 °C per minuut$$,
   $$wiskunde-a-havo-2026-ii-eitje-koken-op-vakantie-context2.png$$,
   $$Om het ei te bereiden, warmt Richard eerst het water van 10 °C op tot de kooktemperatuur. De opwarming verloopt op beide plaatsen lineair met een snelheid van 14,5 °C per minuut. Zodra het water kookt, legt hij er een ei in en laat dit net zo lang in het kokende water liggen tot het hardgekookt is.$$, 'inline'),
  ('839bf88b-65ae-4da5-9f73-e409c77aeae7', '115b084b-5495-4c9d-880d-70a78721c0c0', $$luchtdruk lager in de bergen$$,
   $$wiskunde-a-havo-2026-ii-eitje-koken-op-vakantie-context3.png$$,
   $$De luchtdruk in de bergen is lager dan op zeeniveau. Zie figuur 1, waarin het verband is weergegeven tussen de luchtdruk en de hoogte boven zeeniveau.$$, 'inline'),
  ('6b90feb1-b59d-486e-a471-c0ef3d163726', '115b084b-5495-4c9d-880d-70a78721c0c0', $$figuur 1: luchtdruk tegen hoogte boven zeeniveau$$,
   $$wiskunde-a-havo-2026-ii-eitje-koken-op-vakantie-context4.png$$,
   $$figuur 1
dalende grafiek; verticale as: luchtdruk (mbar) (0 – 1000); horizontale as: hoogte boven zeeniveau (km) (0 – 10)$$, 'inline'),
  ('e886ca8f-9f9b-4583-b595-f3b2e843406e', '115b084b-5495-4c9d-880d-70a78721c0c0', $$kooktemperatuur afhankelijk van luchtdruk$$,
   $$wiskunde-a-havo-2026-ii-eitje-koken-op-vakantie-context5.png$$,
   $$Door de lagere luchtdruk in de bergen, kookt water daar bij een lagere temperatuur dan op zeeniveau. Zie figuur 2, waarin het verband is weergegeven tussen de luchtdruk en de temperatuur waarbij water kookt.$$, 'inline'),
  ('62e3f50d-38b7-40cc-b5a9-8ee117aac6e8', '115b084b-5495-4c9d-880d-70a78721c0c0', $$figuur 2: luchtdruk tegen kooktemperatuur (logaritmische schaal)$$,
   $$wiskunde-a-havo-2026-ii-eitje-koken-op-vakantie-context6.png$$,
   $$figuur 2
stijgende grafiek; verticale as: luchtdruk (mbar), logaritmische schaal (1, 10, 100, 1000); horizontale as: kooktemperatuur water (°C) (0 – 120)$$, 'inline'),
  ('c043c687-aae6-4812-8062-b788ab6f00fe', '115b084b-5495-4c9d-880d-70a78721c0c0', $$2 minuten langer koken op 2000 m; definitie bereidingstijd$$,
   $$wiskunde-a-havo-2026-ii-eitje-koken-op-vakantie-context7.png$$,
   $$Het duurt in de bergen dus korter om het water aan de kook te brengen. Maar door de lagere kooktemperatuur moet een ei op 2000 meter boven zeeniveau 2 minuten langer in het kokende water liggen dan op zeeniveau tot het hardgekookt is. De totale tijd die nodig is om water aan de kook te brengen en om het ei te koken tot het hardgekookt is, noemen we de bereidingstijd.$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('74e9a82f-1019-47c8-a2a8-184aa16a49e2', 'e534c332-b36c-4527-bfa3-388eae1144c2', 1,
   '[{"domain": "Algebra en tellen", "subdomain": "Rekenen"}, {"domain": "Statistiek", "subdomain": "Presentaties van data interpreteren en beoordelen"}]'::jsonb,
   '["staafdiagram aflezen", "percentage van een hoeveelheid", "absolute toename", "procenten", "verschil berekenen"]'::jsonb,
   $$Met percentages uit een staafdiagram en totale hoeveelheden de absolute toename van een deelhoeveelheid berekenen.$$,
   $$wiskunde-a-havo-2026-ii-plasticafval-vraag1.png$$, $$3p 1 Bereken hoeveel miljoen ton plasticafval in 2019 meer werd gerecycled dan in 2005. Geef je antwoord in twee decimalen.$$, array['85376a2d-439c-4d5c-912e-01a414cb385b', '3357ac9f-3440-449c-a382-dff36a35e35b', 'e360598c-cf46-430f-bd13-5bb795cc2033', '1e6bcaa5-62cf-4f8a-88d3-92f2901026f1']::uuid[]),
  ('8bf169c5-b762-4b04-8f9e-7fd2eea6e86d', 'e534c332-b36c-4527-bfa3-388eae1144c2', 2,
   '[{"domain": "Verbanden", "subdomain": "Lineaire verbanden"}]'::jsonb,
   '["lineaire afname", "afname per jaar", "interpolatie", "percentage berekenen", "lineair verband"]'::jsonb,
   $$Met lineaire interpolatie tussen twee gegeven percentages het percentage in een tussenliggend jaar berekenen.$$,
   $$wiskunde-a-havo-2026-ii-plasticafval-vraag2.png$$, $$4p 2 Bereken hoeveel procent van het plasticafval in 2011 werd gestort. Geef je antwoord als geheel getal.$$, array['17c591f7-f527-465e-8cae-07568df78ba8']::uuid[]),
  ('0069e4d1-30a8-40e3-9ab3-31cb3cdaf780', 'e534c332-b36c-4527-bfa3-388eae1144c2', 3,
   '[{"domain": "Verbanden", "subdomain": "Exponentiële verbanden"}]'::jsonb,
   '["groeifactor", "groeipercentage berekenen", "groeifactor per jaar", "procentuele toename", "machtswortel"]'::jsonb,
   $$Uit de procentuele toename over 15 jaar het groeipercentage per jaar berekenen bij exponentiële groei.$$,
   $$wiskunde-a-havo-2026-ii-plasticafval-vraag3.png$$, $$4p 3 Bereken de procentuele toename per jaar. Geef je antwoord in één decimaal.$$, array['c1be39c6-4ea3-4e90-a383-af84f4d46ec5']::uuid[]),
  ('6d488318-65c9-4b11-bbd1-48e8fe823602', 'e534c332-b36c-4527-bfa3-388eae1144c2', 4,
   '[{"domain": "Verbanden", "subdomain": "Lineaire verbanden"}, {"domain": "Verbanden", "subdomain": "Grafieken, vergelijkingen en ongelijkheden"}]'::jsonb,
   '["lineaire formules", "ongelijkheid oplossen", "snijpunt van twee lijnen", "gehele jaren", "lineair verband"]'::jsonb,
   $$Met twee lineaire formules berekenen na hoeveel gehele jaren de ene grootheid voor het eerst groter is dan de andere.$$,
   $$wiskunde-a-havo-2026-ii-plasticafval-vraag4.png$$, $$3p 4 Bereken hoeveel gehele jaren na 2005 dit voor het eerst zo is.$$, array['f9e829bb-a318-4c5e-8e78-346813ceee0c', '62482b2e-918c-4dfe-9c24-e6c515025390']::uuid[]),
  ('62f8ba02-8f9d-445d-b7f7-4cf3491b9b8d', 'e534c332-b36c-4527-bfa3-388eae1144c2', 5,
   '[{"domain": "Verbanden", "subdomain": "Formules met één of meer variabelen"}, {"domain": "Verbanden", "subdomain": "Lineaire verbanden"}]'::jsonb,
   '["formule opstellen", "formules combineren", "richtingscoëfficiënt", "startgetal", "som is 100%"]'::jsonb,
   $$Uit drie lineaire formules en het gegeven dat de percentages samen 100% zijn een lineaire formule voor het vierde percentage opstellen.$$,
   $$wiskunde-a-havo-2026-ii-plasticafval-vraag5.png$$, $$4p 5 Bereken de getallen die op de puntjes in formule 4 moeten staan. Geef je antwoorden in twee decimalen.$$, array['f9e829bb-a318-4c5e-8e78-346813ceee0c', '4524fb95-4fef-40f6-9a40-816e11448bb5']::uuid[]),
  ('3f73c1df-b0fe-4557-9d85-ccd09247f92a', '00694cd3-c83e-4022-9604-66a59ecdb4f0', 6,
   '[{"domain": "Verbanden", "subdomain": "Exponentiële verbanden"}]'::jsonb,
   '["verdubbelingstijd", "groeifactor", "exponentiële groei", "vergelijking oplossen", "gehele jaren"]'::jsonb,
   $$Bij een exponentiële formule berekenen na hoeveel gehele jaren de hoeveelheid minimaal is verdubbeld.$$,
   $$wiskunde-a-havo-2026-ii-huisartsen-vraag6.png$$, $$3p 6 Bereken hoeveel gehele jaren het volgens formule 1 minimaal duurt voordat het aantal wisselende waarnemers is verdubbeld.$$, array['7882bfef-5e32-4bf3-94d5-9dcbdf3fac47', '30acb7c4-3332-408a-b4ec-54fe22215fa9']::uuid[]),
  ('7d42a9e5-5fa8-4b9b-82ca-c11c405f2c97', '00694cd3-c83e-4022-9604-66a59ecdb4f0', 7,
   '[{"domain": "Algebra en tellen", "subdomain": "Rekenen"}, {"domain": "Verbanden", "subdomain": "Lineaire verbanden"}]'::jsonb,
   '["procentuele toename", "beginwaarde terugrekenen", "toename per jaar", "lineaire groei", "decimalen"]'::jsonb,
   $$Uit de eindwaarde en de procentuele toename de beginwaarde terugrekenen en de jaarlijkse lineaire toename berekenen.$$,
   $$wiskunde-a-havo-2026-ii-huisartsen-vraag7.png$$, $$3p 7 Voer deze berekening uit en geef je antwoord in één decimaal.$$, array['4a49aaa2-208e-4a25-98c2-851024a3b3fc']::uuid[]),
  ('becbf4d3-a15a-4b5e-83a4-a5dee2b8656d', '00694cd3-c83e-4022-9604-66a59ecdb4f0', 8,
   '[{"domain": "Verbanden", "subdomain": "Grafieken, vergelijkingen en ongelijkheden"}, {"domain": "Verbanden", "subdomain": "Exponentiële verbanden"}, {"domain": "Verbanden", "subdomain": "Lineaire verbanden"}]'::jsonb,
   '["exponentiële formule", "lineaire formule", "ongelijkheid oplossen", "snijpunt", "helft van een totaal", "jaartal bepalen"]'::jsonb,
   $$Met een exponentiële en een lineaire formule bepalen in welk jaar de ene grootheid voor het eerst meer is dan de helft van de andere.$$,
   $$wiskunde-a-havo-2026-ii-huisartsen-vraag8.png$$, $$4p 8 Bereken met behulp van formule 1 en 2 in welk jaar op 1 januari het aantal wisselende waarnemers voor het eerst meer is dan de helft van het totaal aantal huisartsen.$$, array['7882bfef-5e32-4bf3-94d5-9dcbdf3fac47', '30acb7c4-3332-408a-b4ec-54fe22215fa9', '1750db2b-b7f5-4dff-ac20-a053f727340c']::uuid[]),
  ('5187c7d1-ab18-45e9-b21f-12163b0df149', '00694cd3-c83e-4022-9604-66a59ecdb4f0', 9,
   '[{"domain": "Statistiek", "subdomain": "Statistische uitspraken doen"}, {"domain": "Statistiek", "subdomain": "Presentaties van data interpreteren en beoordelen"}]'::jsonb,
   '["verschil tussen groepen", "cumulatieve percentages", "maximaal verschil in cumulatief percentage", "effectgrootte", "ordinale variabele", "formuleblad"]'::jsonb,
   $$Met de vuistregels van het formuleblad op basis van percentages per antwoordcategorie onderzoeken of het verschil tussen twee groepen groot, middelmatig of gering is.$$,
   $$wiskunde-a-havo-2026-ii-huisartsen-vraag9.png$$, $$4p 9 Onderzoek met behulp van het formuleblad of dit verschil groot, middelmatig of gering is.$$, array['91f9903a-b9db-4566-856e-7b6467ac1529', 'fceee8f3-8bbf-448c-b2f9-d1d562b98c9d', 'fa13f86f-4519-436d-a061-8cd9da8585a9']::uuid[]),
  ('3ed120f1-f22f-4723-b3ac-ae11084f1145', '00694cd3-c83e-4022-9604-66a59ecdb4f0', 10,
   '[{"domain": "Statistiek", "subdomain": "Statistische uitspraken doen"}, {"domain": "Statistiek", "subdomain": "Data en verdelingen"}]'::jsonb,
   '["betrouwbaarheidsinterval", "steekproefproportie", "steekproefomvang berekenen", "standaardfout", "95%-betrouwbaarheidsinterval", "formuleblad"]'::jsonb,
   $$Uit een gegeven 95%-betrouwbaarheidsinterval voor een proportie de steekproefomvang terugrekenen.$$,
   $$wiskunde-a-havo-2026-ii-huisartsen-vraag10.png$$, $$4p 10 Bereken met behulp van het formuleblad de steekproefomvang onder de geneeskundestudenten in het zesde studiejaar.$$, array['abf1c1b2-d4fd-49f8-a20c-61422795a44f']::uuid[]),
  ('16b8dade-48bc-4d9b-9f46-c3e8441d2176', 'e653d16a-853a-4f23-8e84-bff662ac71ee', 11,
   '[{"domain": "Verbanden", "subdomain": "Formules met één of meer variabelen"}, {"domain": "Algebra en tellen", "subdomain": "Rekenen"}]'::jsonb,
   '["formule met breuk", "substitueren", "verhouding", "eenheden omrekenen", "verschil berekenen"]'::jsonb,
   $$Met de formule V = S/L uit lengte en verhouding de spanwijdte berekenen en het verschil in centimeters bepalen.$$,
   $$wiskunde-a-havo-2026-ii-spanwijdte-en-lichaamslengte-vraag11.png$$, $$3p 11 Bereken het verschil in spanwijdte tussen deze twee vechters. Geef je antwoord in hele centimeters.$$, array['52c2c6ad-5cc5-41c8-96fd-81a297dde8bf', 'f4a3de23-0660-4a8b-aa83-7da9cb18b5b3']::uuid[]),
  ('066f08a0-2ac6-4395-a0b5-16c078b3e1ad', 'e653d16a-853a-4f23-8e84-bff662ac71ee', 12,
   '[{"domain": "Verbanden", "subdomain": "Formules met één of meer variabelen"}]'::jsonb,
   '["verhouding", "breuk interpreteren", "omgekeerd evenredig", "formule redeneren", "noemer en teller"]'::jsonb,
   $$Met de formule V = S/L redeneren welke lengte bij een kleinere of grotere verhouding hoort bij gelijke teller.$$,
   $$wiskunde-a-havo-2026-ii-spanwijdte-en-lichaamslengte-vraag12.png$$, $$2p 12 Leg uit welke van de twee vechters dan de grootste lichaamslengte heeft.$$, array['52c2c6ad-5cc5-41c8-96fd-81a297dde8bf', '684925c1-1a78-41ee-a59c-2acf461b79c2']::uuid[]),
  ('e537f81e-49de-4f85-b499-6865e10701ce', 'e653d16a-853a-4f23-8e84-bff662ac71ee', 13,
   '[{"domain": "Verbanden", "subdomain": "Formules met één of meer variabelen"}, {"domain": "Algebra en tellen", "subdomain": "Algebra"}]'::jsonb,
   '["vergelijking oplossen", "substitutie", "formule met breuk", "variabele vrijmaken", "verhouding"]'::jsonb,
   $$Door substitutie van S = L + 0,025 in V = S/L een vergelijking opstellen en oplossen naar L.$$,
   $$wiskunde-a-havo-2026-ii-spanwijdte-en-lichaamslengte-vraag13.png$$, $$3p 13 Bereken de lichaamslengte van deze vechter in meter. Geef je antwoord in twee decimalen.$$, array['52c2c6ad-5cc5-41c8-96fd-81a297dde8bf', 'ad128c61-0364-4307-bd1e-ae1966e6f177']::uuid[]),
  ('6a48d566-d2e9-43a5-a2ab-776e1ea8a722', 'e653d16a-853a-4f23-8e84-bff662ac71ee', 14,
   '[{"domain": "Statistiek", "subdomain": "Statistische uitspraken doen"}]'::jsonb,
   '["effectgrootte", "gemiddelde", "standaardafwijking", "verschil tussen groepen", "formuleblad"]'::jsonb,
   $$Met gemiddelden en standaardafwijkingen uit een tabel via de effectgrootte beoordelen of het verschil tussen twee groepen groot, middelmatig of gering is.$$,
   $$wiskunde-a-havo-2026-ii-spanwijdte-en-lichaamslengte-vraag14.png$$, $$3p 14 Onderzoek met behulp van het formuleblad of het verschil in de verhouding V tussen de gewichtsklassen ‘vlieggewicht’ en ‘lichtgewicht’ groot, middelmatig of gering is.$$, array['52c2c6ad-5cc5-41c8-96fd-81a297dde8bf', '338e90ae-d691-49e7-92bf-06789098fcf4']::uuid[]),
  ('4b4f1792-4017-4033-81a3-5dae0f6c334f', 'e653d16a-853a-4f23-8e84-bff662ac71ee', 15,
   '[{"domain": "Statistiek", "subdomain": "Presentaties van data interpreteren en beoordelen"}, {"domain": "Statistiek", "subdomain": "Statistische uitspraken doen"}]'::jsonb,
   '["boxplot", "kwartielen", "mediaan", "boxplots vergelijken", "uitspraken beoordelen", "formuleblad"]'::jsonb,
   $$Met boxplots en de vuistregels van het formuleblad nagaan of uitspraken over kwartielen, mediaan en verschillen tussen groepen juist zijn.$$,
   $$wiskunde-a-havo-2026-ii-spanwijdte-en-lichaamslengte-vraag15.png$$, $$3p 15 Leg van elke uitspraak uit of deze juist is.$$, array['52c2c6ad-5cc5-41c8-96fd-81a297dde8bf', '84255718-11b3-4148-82e2-3554ec861366']::uuid[]),
  ('c05af4d1-32f1-407e-a717-85bcc6ed2ddb', '4061ef4d-3999-4dad-9f6f-43c9a0d053e3', 16,
   '[{"domain": "Verbanden", "subdomain": "Grafieken, vergelijkingen en ongelijkheden"}, {"domain": "Statistiek", "subdomain": "Presentaties van data interpreteren en beoordelen"}]'::jsonb,
   '["grafiek aflezen", "complementair percentage", "percentage kapot", "verschil bepalen", "cumulatieve grafiek"]'::jsonb,
   $$Uit twee grafieken van het percentage kapot het tijdstip aflezen waarop nog 25% werkt en het verschil bepalen.$$,
   $$wiskunde-a-havo-2026-ii-levensduur-van-apparaten-vraag16.png$$, $$3p 16 Bepaal het verschil in jaren tussen deze twee aantallen gebruiksjaren. Geef je antwoord in één decimaal en licht je antwoord toe.$$, array['6229285a-7eef-4164-8b1e-9b5732806aaf', '7f040bfc-a885-447d-b82a-3c3dd031b7c1', '666b1b39-dbe4-462f-bb5b-b3f15dd09339', '4f40b288-7df6-493f-a9b9-0ebc0d8776ef', '70a2ef27-b0a5-41d9-937f-09197466dd7f']::uuid[]),
  ('55211235-c684-40d2-a722-2613883552dc', '4061ef4d-3999-4dad-9f6f-43c9a0d053e3', 17,
   '[{"domain": "Algebra en tellen", "subdomain": "Algebra"}, {"domain": "Verbanden", "subdomain": "Formules met één of meer variabelen"}]'::jsonb,
   '["formule herleiden", "rekenregels machten", "haakjes wegwerken", "substitutie", "exponent vereenvoudigen"]'::jsonb,
   $$Door invullen van parameters en toepassen van rekenregels voor machten een formule herleiden tot een gegeven vorm.$$,
   $$wiskunde-a-havo-2026-ii-levensduur-van-apparaten-vraag17.png$$, $$4p 17 Geef deze herleiding.$$, array['a6a5058c-c71c-4487-aa7c-5c1bd2b86409', 'e2117254-6879-4c25-80cc-411a169a335e']::uuid[]),
  ('5dca64ea-b20a-49c1-a538-44892da51212', '4061ef4d-3999-4dad-9f6f-43c9a0d053e3', 18,
   '[{"domain": "Verbanden", "subdomain": "Formules met één of meer variabelen"}, {"domain": "Verbanden", "subdomain": "Exponentiële verbanden"}]'::jsonb,
   '["formule invullen", "toename in een tijdsinterval", "verschil van functiewaarden", "percentage berekenen", "afronden"]'::jsonb,
   $$Met een formule het percentage berekenen dat in een bepaald tijdsinterval bijkomt als verschil van twee functiewaarden.$$,
   $$wiskunde-a-havo-2026-ii-levensduur-van-apparaten-vraag18.png$$, $$3p 18 Bereken hoeveel procent van de broodroosters volgens formule 2 gedurende het derde gebruiksjaar kapot zal gaan. Geef je antwoord in hele procenten.$$, array['e2117254-6879-4c25-80cc-411a169a335e']::uuid[]),
  ('4f4d84e5-9a6f-488c-a6c9-fb9e41f07a2f', '4061ef4d-3999-4dad-9f6f-43c9a0d053e3', 19,
   '[{"domain": "Verbanden", "subdomain": "Grafieken, vergelijkingen en ongelijkheden"}, {"domain": "Verbanden", "subdomain": "Exponentiële verbanden"}]'::jsonb,
   '["op den duur", "limietgedrag", "grondtal kleiner dan 1", "macht nadert naar 0", "redeneren met formule", "grenswaarde"]'::jsonb,
   $$Met de structuur van een formule met grondtal kleiner dan 1 beredeneren dat het percentage op den duur naar 100 nadert.$$,
   $$wiskunde-a-havo-2026-ii-levensduur-van-apparaten-vraag19.png$$, $$3p 19 Beredeneer dit met behulp van formule 2, zonder gebruik te maken van getallenvoorbeelden.$$, array['e2117254-6879-4c25-80cc-411a169a335e', 'e8022f23-700a-49cd-956b-79b39b532e66']::uuid[]),
  ('2c751259-398c-4e82-acd4-42f851476046', '4061ef4d-3999-4dad-9f6f-43c9a0d053e3', 20,
   '[{"domain": "Verbanden", "subdomain": "Formules met één of meer variabelen"}, {"domain": "Verbanden", "subdomain": "Grafieken, vergelijkingen en ongelijkheden"}, {"domain": "Algebra en tellen", "subdomain": "Rekenen"}]'::jsonb,
   '["parameter berekenen", "vergelijking oplossen", "percentage berekenen", "numeriek oplossen", "formule invullen"]'::jsonb,
   $$Uit een gegeven percentage en tijdstip met een formule de onbekende parameter berekenen door een vergelijking op te lossen.$$,
   $$wiskunde-a-havo-2026-ii-levensduur-van-apparaten-vraag20.png$$, $$4p 20 Bereken met behulp van formule 1 de waarde van s die bij deze stofzuigers hoort. Geef je antwoord in één decimaal.$$, array['a6a5058c-c71c-4487-aa7c-5c1bd2b86409', '9493cc35-8938-4fdf-afaf-8f2f59bfd4a6']::uuid[]),
  ('bd3c6ffe-a038-4ead-bb79-f6bd71b5d4d6', '115b084b-5495-4c9d-880d-70a78721c0c0', 21,
   '[{"domain": "Verbanden", "subdomain": "Grafieken, vergelijkingen en ongelijkheden"}, {"domain": "Verbanden", "subdomain": "Lineaire verbanden"}, {"domain": "Algebra en tellen", "subdomain": "Rekenen"}]'::jsonb,
   '["grafiek aflezen", "logaritmische schaal", "lineaire opwarming", "tijd berekenen", "minuten en seconden omrekenen", "verschil berekenen"]'::jsonb,
   $$Met twee grafieken (waarvan één met logaritmische schaal) en een lineaire opwarming de bereidingstijden op twee hoogtes berekenen en vergelijken.$$,
   $$wiskunde-a-havo-2026-ii-eitje-koken-op-vakantie-vraag21.png$$, $$7p 21 Onderzoek of de bereidingstijd van een ei op 2000 meter boven zeeniveau langer of korter is dan op zeeniveau en bereken het verschil in bereidingstijd. Geef je antwoord in hele seconden.$$, array['6336f397-9efd-423b-b820-80205f60a9e8', '82d498e1-7437-4936-807f-543423a7d10f', '839bf88b-65ae-4da5-9f73-e409c77aeae7', '6b90feb1-b59d-486e-a471-c0ef3d163726', 'e886ca8f-9f9b-4583-b595-f3b2e843406e', '62e3f50d-38b7-40cc-b5a9-8ee117aac6e8', 'c043c687-aae6-4812-8062-b788ab6f00fe']::uuid[]);
